import 'reflect-metadata';
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { passwordHash, passwordMatches } from '../apps/api/src/auth/password';
// Non-operational fixture generated by node-argon2 0.45.2 before removing the addon.
const nativeHash =
  '$argon2id$v=19$m=19456,t=2,p=1$TjSryQRf226oNDbxqWS27A$wau7RdI63Gd/wzS+SvI3P1K0myZ9HrkjTezZHJCPQQg';
const password = 'Compatibilidad-Contraseña-2026';
test('portable Argon2id verifies an existing native PHC hash without a password reset', async () => {
  assert.equal(await passwordMatches(nativeHash, password), true);
  assert.equal(await passwordMatches(nativeHash, password + '!'), false);
});
test('portable hashing preserves work factors, random salts and independent concurrent results', async () => {
  const [first, second] = await Promise.all([
    passwordHash(password),
    passwordHash(password),
  ]);
  assert.match(first, /^\$argon2id\$v=19\$m=19456,t=2,p=1\$/);
  assert.notEqual(first, second);
  assert.deepEqual(
    await Promise.all([
      passwordMatches(first, password),
      passwordMatches(second, password),
      passwordMatches(first, 'otro-password'),
    ]),
    [true, true, false],
  );
});
test('malformed, changed or unsupported hashes fail closed', async () => {
  for (const hash of [
    '',
    nativeHash + '=',
    nativeHash.replace('m=19456', 'm=999999999'),
    nativeHash.replace('argon2id', 'argon2i'),
    nativeHash.replace('v=19', 'v=16'),
    nativeHash.slice(0, -1) + 'A',
  ])
    assert.equal(await passwordMatches(hash, password), false);
});
